import { NotForYou } from "march/landing"

// huysuz kediyi sahiplenmek: sana uymayan satırların üstünü çiz; hepsi çizilince kedi senindir
const LINES = [
  { text: "Sabah 5'te uyanmaktan nefret ediyorsun", instead: "Erkenci kuşsun: kahvaltı saati kedinle aynı." },
  { text: "Kanepene bir şey olmasın istiyorsun", instead: "Kanepe zaten eskiydi." },
  { text: "Sevgi gösterisi bekliyorsun", instead: "Haftada bir mırıltı sana yeter." },
]

export function GrumpyCat() {
  let $count = 0
  return <div sx={{ flex: "col", gap: 2 }}>
    <strong sx={{ text: "xl" }}>{$count === LINES.length ? "😼 Pamuk artık senin!" : "😾 Pamuk'u sahiplenmek ister misin?"}</strong>
    <NotForYou check title="Pamuk sana göre değil, eğer…" items={LINES} onCheck={(m: number[]) => $count = m.length}
      hint="Sen değil misin? Dokun" markedHint="Tamam, sen değilsin"
      verdict={(n: number, total: number) => (n === total ? "Pamuk seni onayladı." : `${total - n} engel kaldı.`)} />
  </div>
}

import { NotForYou } from "march/landing"

// haftalık yemek kutusu sitesinde dürüst bir bölüm: kimin için olmadığı, kimin için olduğu
export function MealKitFit() {
  return <section sx={{ flex: "col", gap: 3 }}>
    <h2>Tencere Kutusu herkese göre değil</h2>
    <p sx={{ color: "muted" }}>Para vermeden önce dürüstçe söyleyelim: bazı durumlarda başka bir seçenek sana daha iyi gelir.</p>
    <NotForYou check title="Sana göre değil, eğer…" forYouTitle="Tam sana göre, eğer…"
      items={[
        { text: "Hiç yemek yapmak istemiyorsun", detail: "Kutuda malzeme var, hazır yemek yok. Hazır yemek servisi sana daha uygun.", instead: "Yarım saat mutfakta olmak sana iyi geliyor." },
        { text: "Her gün evde değilsin", detail: "Kutu salı günü gelir, malzemeler beş gün tazedir.", instead: "Haftanın çoğu akşamı evdesin." },
        { text: "Bütçen öğün başına 80 ₺'nin altında", detail: "Öğün başına 120 ₺'den başlıyoruz.", instead: "Pazara gitmeye ayırdığın zamanı paraya değer buluyorsun." },
      ]}
      forYou={[
        { text: "Ne pişireceğini düşünmekten yoruldun", detail: "Her hafta altı yeni tarif." },
        { text: "Israftan kaçınıyorsun", detail: "Malzemeler tarif kadar, gramıyla." },
      ]} />
  </section>
}

import { NotForYou } from "march/landing"
import { Segmented, Toggle, Card } from "march/ui"

// NotForYou'nun bütün özellikleri bir arada: satırlar (metin, açıklama, olumlu yanı), kimin için olduğu, iki başlık,
// işaretleme, kendi sonuç metnin, kartlar / liste, onCheck, kart etiketi, iki ipucu, kendi işaretlerin ve sınıf
const ITEMS = [
  { text: "Gece yarısı kod yazmayı sevmiyorsun", detail: "Topluluk en çok gece canlı.", instead: "Gece kuşusun: canlı yayınlar tam saatinde." },
  { text: "Yalnız çalışmak istiyorsun", detail: "Her proje bir ekiple yapılır.", instead: "Ekip işini seviyorsun." },
  { text: "Hazır cevap arıyorsun", detail: "Burada soru sorulur, birlikte bulunur.", instead: "Kendin bulmaktan keyif alıyorsun." },
]
const MARKS = { not: "🙅", marked: "🎉", for: "👍" }

export function NotForYouLab() {
  let $variant: "cards" | "list" = "cards"
  let $own = false
  let $marked: number[] = []
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Segmented aria-label="Görünüm" options={[{ value: "cards", label: "kartlar" }, { value: "list", label: "liste" }]} bind:value={$variant} />
        <Toggle label="Kendi işaretlerim" bind:value={$own} />
      </div>
    </Card>
    {() => { const variant = $variant, own = $own; return <NotForYou class="lab-nfy" variant={variant} check items={ITEMS}
      forYou={[{ text: "Birlikte öğrenmeyi seviyorsun", detail: "Haftalık eşli programlama." }]}
      title="Kulübe göre değilsin, eğer…" forYouTitle="Kulüp seni bekliyor, eğer…"
      verdict={(n: number, total: number) => (n === total ? "Hoş geldin, kulüp senin!" : `${n} / ${total} çizildi`)}
      onCheck={(m: number[]) => $marked = m}
      meLabel="Bu benim" hint="Değil mi? Dokun" markedHint="Değilmişsin"
      mark={own ? (state: keyof typeof MARKS) => MARKS[state] : true} /> }}
    <p sx={{ color: "muted" }} class="lab-marked">Çizilenler: {$marked.join(", ") || "yok"}</p>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { NotForYouLab } from "./NotForYouLab.tsx"

// NotForYouLab'in testleri: kaydedince Testler sekmesinde çalışır
test("iki başlık ve kendi sonuç metni", () => {
  const s = renderTest(() => <NotForYouLab />)
  const titles = s.all(".lab-nfy .m-nfy-title").map((e: Element) => e.textContent)
  expect(titles).toEqual(["Kulübe göre değilsin, eğer…", "Kulüp seni bekliyor, eğer…"])
  expect(s.get(".m-nfy-verdict")?.textContent).toBe("0 / 3 çizildi")
})

test("bir satıra basınca üstü çizilir, onCheck sırayı yazar", async () => {
  const s = renderTest(() => <NotForYouLab />)
  await s.click("Yalnız çalışmak istiyorsun")
  const boxes = s.all('.lab-nfy [role="checkbox"]')
  expect(boxes[1]!.getAttribute("aria-checked")).toBe("true")
  expect(s.get(".lab-marked")?.textContent).toBe("Çizilenler: 1")
  expect(s.text()).toContain("Değilmişsin")
})

test("hepsi çizilince hoş geldin", async () => {
  const s = renderTest(() => <NotForYouLab />)
  for (const t of ["Gece yarısı kod yazmayı sevmiyorsun", "Yalnız çalışmak istiyorsun", "Hazır cevap arıyorsun"]) await s.click(t)
  expect(s.get(".m-nfy-verdict")?.textContent).toBe("Hoş geldin, kulüp senin!")
})

test("liste görünümü ve kart etiketi", async () => {
  const s = renderTest(() => <NotForYouLab />)
  expect(s.all(".m-nfy-me-label").length).toBe(3)
  expect(s.get(".m-nfy-me-label")?.textContent).toBe("Bu benim")
  await s.click("liste")
  expect(s.get(".lab-nfy")?.classList.contains("m-nfy-v-list")).toBe(true)
})
